mod = 1000000007

def istrue(st, p, n, lis, lcm):
	if lcm[st][st][p] != -1 and lis[st] != lcm[st][st][p]:
		return 0
	for j in range(1, n + 1):
		if j == st or lcm[st][j][p] == -1:
			continue
		if max(lis[st], lis[j]) != lcm[st][j][p]:
			return 0
	return 1

def getans(st, pr, n, lis, lcm):
	if st > n:
		for i in range(1, n + 1):
			if istrue(i, pr, n, lis, lcm) == 0:
				return 0
		return 1
	(mmax, ans) = (-1, 0)
	if lcm[st][st][pr] != -1:
		lis[st] = lcm[st][st][pr]
	else:
		for j in range(1, n + 1):
			if j == st or lcm[st][j][pr] == -1:
				continue
			if lis[j] == -2:
				lis[st] = lcm[st][j][pr]
			if mmax == -1 or mmax > lcm[st][j][pr]:
				mmax = lcm[st][j][pr]
	if lis[st] != -1:
		ans = getans(st + 1, pr, n, lis, lcm)
	elif mmax == -1:
		ans = getans(st + 1, pr, n, lis, lcm)
		if ans != 0:
			return -1
		else:
			return 0
	elif mmax == 0:
		lis[st] = 0
		ans = getans(st + 1, pr, n, lis, lcm)
	else:
		(an1, an2) = (0, 0)
		lis[st] = -2
		an1 = getans(st + 1, pr, n, lis, lcm)
		lis[st] = mmax
		an2 = getans(st + 1, pr, n, lis, lcm)
		if an1 == -1 or an2 == -1:
			ans = -1
		else:
			ans = (an1 * mmax + an2) % mod
	lis[st] = -1
	return ans
